<?php
require_once __DIR__.'/functions.php';$admin=require_admin();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['user_id']??0);$mb=(int)($_POST['quota_mb']??100);if($mb<1||$mb>10240){flash('Kuota harus antara 1 dan 10240 MB.','error');}else{$s=$pdo->prepare("UPDATE users SET quota_bytes=? WHERE id=? AND role='student'");$s->execute([$mb*1024*1024,$id]);flash('Kuota mahasiswa berhasil diperbarui.');}redirect('admin.php');}$users=$pdo->query("SELECT u.id,u.name,u.email,u.role,u.quota_bytes,u.created_at,COALESCE(SUM(f.size_bytes),0) used FROM users u LEFT JOIN files f ON f.user_id=u.id GROUP BY u.id ORDER BY u.created_at DESC")->fetchAll();page_header('Admin');?><div class="page-heading"><div><div class="eyebrow">PENGELOLAAN SISTEM</div><h1>Dashboard Admin</h1><p class="muted">Pantau akun dan kapasitas penyimpanan mahasiswa.</p></div><span class="role-pill admin-pill">ADMIN</span></div><section class="panel"><h2>Daftar pengguna</h2><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Email</th><th>Peran</th><th>Terpakai</th><th>Kuota</th><th>Atur kuota (MB)</th></tr></thead><tbody><?php foreach($users as $x): ?><tr><td><?=e($x['name'])?></td><td><?=e($x['email'])?></td><td><?=e($x['role'])?></td><td><?=e(format_bytes((int)$x['used']))?></td><td><?=e(format_bytes((int)$x['quota_bytes']))?></td><td><?php if($x['role']==='student'): ?><form method="post" class="quota-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="user_id" value="<?=$x['id']?>"><input type="number" name="quota_mb" min="1" max="10240" value="<?= (int)($x['quota_bytes']/1048576) ?>"><button class="secondary small">Simpan</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php page_footer(); ?>
